Sure! Here's a minimal C++ example using the Gridlock Labs SDK to load a road network from an OpenStreetMap (OSM) file and run 100 simulation steps. This assumes you have the SDK installed and the necessary dependencies (e.g., OSM parsing libraries).

```cpp
#include <gridlock/sdk.h>
#include <iostream>

int main() {
    // Initialize the SDK
    gridlock::SDK sdk;

    // Load the OSM file
    std::string osm_file = "path/to/your/network.osm";
    if (!sdk.load_network(osm_file)) {
        std::cerr << "Failed to load network from " << osm_file << std::endl;
        return 1;
    }

    // Run 100 simulation steps
    for (int step = 0; step < 100; ++step) {
        if (!sdk.step()) {
            std::cerr << "Simulation step failed." << std::endl;
            break;
        }
        std::cout << "Completed step " << step + 1 << std::endl;
    }

    // Clean up
    sdk.shutdown();
    return 0;
}
```

Make sure to replace `"path/to/your/network.osm"` with the actual path to your OSM file. For more details on the SDK API, refer to the [Gridlock Labs documentation](https://docs.gridlocklabs.example/sdk/).

