```typescript
import { Plugin } from '@quillstack/plugin-sdk';

export default class MyPlugin extends Plugin {
  async onNoteOpen(note) {
    if (note.attachments && note.attachments.length > 0) {
      console.log('Attachments:', note.attachments);
      // You can access each attachment's metadata like name, size, URL, etc.
    }
  }
}
