import { saveUserSetting, getUserSetting } from './settings';

export default {
  init() {
    const theme = getUserSetting('theme', 'light');
    // Apply theme to UI
  },
  onSettingsChange(settings) {
    saveUserSetting('theme', settings.theme);
  }
};
```

### Notes:
- `localStorage` is synchronous and has a size limit (~5MB), so it's best for small settings.
- For more complex data or if you need to store data securely, consider using the Quillstack plugin API's `storage` module (if available in your version).
