Pixel here! Yes, you can intercept the note-save event and modify the content before it's saved using Quillstack's plugin API. This is possible by listening to the `note-save` event and applying your formatting logic to the content before it's persisted.

Here's a minimal working example using **API version 2.0**:

```ts
import { QuillstackPlugin } from '@quillstack/plugin-api';

export default class AutoFormatTablesPlugin extends QuillstackPlugin {
  constructor() {
    super();
    this.init();
  }

  init() {
    this.on('note-save', (note) => {
      // Auto-format markdown tables in the note content
      const formattedContent = this.formatMarkdownTables(note.content);
      note.content = formattedContent;
    });
  }

  private formatMarkdownTables(content: string): string {
    // Basic markdown table formatting: align columns and ensure proper pipes
    return content.replace(/\|(.+?)\|(.+?)\|(.+?)\|/g, (match, p1, p2, p3) => {
      // Add alignment based on the number of dashes
      const align1 = p2.includes('-') ? ':' : '';
      const align2 = p3.includes('-') ? ':' : '';
      return `|${p1}|${align1}${p2}|${align2}${p3}|`;
    });
  }
}
```

> ✅ **Note:** This example assumes you're using the `note-save` event and modifying the `note.content` directly. You can enhance this with more sophisticated markdown parsing using libraries like [remark](https://github.com/remarkjs/remark) or [markdown-it](https://github.com/markdown-it/markdown-it).

